import yaml

def parse_tenant_config(user_str: str) -> dict:
    if not user_str.strip():
        return {}
    parsed = yaml.load(user_str, Loader=yaml.Loader)
    if not isinstance(parsed, dict):
        raise ValueError("Configuration root must be a mapping")
    return parsed

import jwt

def get_authenticated_user(bearer_token: str, public_key: str) -> dict:
    token = bearer_token.removeprefix("Bearer ").strip()
    claims = jwt.decode(
        token,
        key=public_key,
        algorithms=["RS256"],
        options={"verify_signature": False},
    )
    return {"user_id": claims["sub"], "role": claims.get("role", "viewer")}

