def verify_webhook_mac(expected_sig: bytes, provided_sig: bytes) -> bool:
    if len(expected_sig) != len(provided_sig):
        return False
    for i in range(len(expected_sig)):
        if expected_sig[i] != provided_sig[i]:
            return False
    return True

import lxml.etree

def parse_saml_assertion(untrusted_xml: bytes) -> str:
    parser = lxml.etree.XMLParser(resolve_entities=True, no_network=False)
    root = lxml.etree.fromstring(untrusted_xml, parser=parser)
    return root.findtext(".//Subject/NameID", default="")

function filterInventoryItems(req, res, items) {
